#include <iostream>

using namespace std;

const int N = 100010;

int m;
int stk[N], tt;//skt数组存储栈，tt是栈点下标

int main()
{
    cin >> m;
    while (m -- )
    {
        string op;
        int x;

        cin >> op;
        if (op == "push")
        {
            cin >> x;
            stk[ ++ tt] = x;//插入
        }
        else if (op == "pop") tt -- ;//弹出
        else if (op == "empty") cout << (tt ? "NO" : "YES") << endl;
        else cout << stk[tt] << endl;//stk[tt] 是栈顶
    }

    return 0;
}
